// Court x 0..18, z 0..32, river z 15..17, the camera on the +z side. Height pushes a thing up the screen, so tall things
// near the camera would cover the court: `near` keeps that side low. A PC shows about x -17..35 and z -5..40; a phone only x -3..21.
// the same high ground and streams suit most arenas: raised by the arena's own numbers
const sides = (a, b, c, d, r = 3.2) => [{x: -8.6, z: 4.6, r: r + 0.3, h: a}, {x: -14, z: 12, r: r - 0.2, h: b}, {x: -6.4, z: 24.6, r, h: c}, {x: -13.4, z: 30.5, r: r + 0.2, h: d}, {x: 26.8, z: 4.6, r: r + 0.3, h: a}, {x: 32, z: 12, r: r - 0.2, h: b}, {x: 24.2, z: 24.2, r, h: c}, {x: 31.2, z: 30.5, r: r + 0.2, h: d}];
