const heroes = (p, s = 1) => [{p, x: -9, z: 4.8, ry: 0.55, s}, {p, x: 27, z: 4.8, ry: -0.55, s}];
// laying a room out: mirrored about the court's middle, the way the references are; a row of spots; a row with a size
const mir = a => a.flatMap(p => [p, [18 - p[0], ...p.slice(1)]]);
const row = (x0, z0, x1, z1, n, s = 1) => Array.from({length: n}, (_, i) => { const t = n > 1 ? i / (n - 1) : 0.5; return [x0 + (x1 - x0) * t, z0 + (z1 - z0) * t, s]; });
const mirStage = a => a.flatMap(P => [P, {...P, x: 18 - P.x}]);
// spots along a curve about a centre, turned to face it; a loose cluster; a piece given as a path; a path and its mirror image
const arcAt = (cx, cz, r, a0, a1, n, s = 1, y, face = true) => Array.from({length: n}, (_, i) => { const a = (n > 1 ? a0 + (a1 - a0) * i / (n - 1) : a0) * Math.PI / 180, ca = Math.cos(a), sa = Math.sin(a); return [cx + ca * r, cz + sa * r, s, y, face ? Math.atan2(-ca, -sa) : undefined]; });
const clus = (x, z, n, r, s = 1, seed = 1) => Array.from({length: n}, (_, i) => { const a = i * 2.399 + seed, d = r * Math.sqrt((i + 0.5) / n); return [x + Math.cos(a) * d, z + Math.sin(a) * d, s * (0.82 + ((i * 7 + seed * 3) % 5) * 0.09)]; });
const paths = (k, L, spec) => L.map(pts => ({k, at: [[0, 0]], shade: 0, pts, ...spec}));
const mirP = L => L.flatMap(P => [P, P.map(q => [18 - q[0], ...q.slice(1)])]);
// a curved gallery and its twin on the other side of the court
const gallery = spec => [{k: 'balcony', at: [[0, 0]], shade: 0, ...spec}, {k: 'balcony', at: [[0, 0]], shade: 0, ...spec, cx: 18 - spec.cx, a0: 180 - spec.a0, a1: 180 - spec.a1}];
const walls = (c, trim, win, gain, h = 15, bay = 5.2) => [{k: 'wall', at: [[0, 0]], shade: 0, from: [-90, -4.2], to: [108, -4.2], h, bay, c, trim, win, gain}];
